<script setup>
import {computed,ref,watch} from 'vue';
import {api,yuan,units,today,cents,fileBase64} from './api.js';
const props=defineProps({page:String,state:Object,filter:Object});
const emit=defineEmits(['changed','navigate']);
const query=ref(''),status=ref(''),customer=ref(''),month=ref(''),endBefore=ref(''),onlyOverdue=ref(false),expiresSoon=ref(false),expired=ref(false);
const error=ref(''),notice=ref(''),busy=ref(false),modal=ref(''),form=ref({}),files=ref([]),detail=ref(null),restoreFile=ref(null),restoreConfirm=ref('');
const stepLabels={collect:'资料收集',sort:'票据整理',book:'记账',review:'复核',tax:'申报准备 / 处理'};
const stepKeys=Object.keys(stepLabels);
const meta={customers:{title:'客户管理',desc:'每一家企业，都有清晰完整的服务档案。',add:'新增客户'},contracts:{title:'代账合同',desc:'管理服务约定、合同费用与到期续签。',add:'新增合同'},tasks:{title:'月度代账任务',desc:'从资料收集到申报准备，让每月工作有序推进。',add:'建立月度任务'},bills:{title:'票据管理',desc:'手动登记票据，原始附件随本地数据库一同保存。',add:'登记票据'},receivables:{title:'应收与收款',desc:'按合同管理应收，每一笔回款都有据可查。',add:'新增应收'},reports:{title:'业务汇总',desc:'由客户、任务和收款记录实时汇总。'},maintenance:{title:'数据维护',desc:'数据保存在本机；定期备份，让工作更安心。'}};
const cfg=computed(()=>meta[props.page]||meta.customers);
const customers=computed(()=>props.state.customers||[]);
const cname=id=>customers.value.find(x=>x.id===Number(id))?.name||'—';
const ctitle=id=>props.state.contracts?.find(x=>x.id===Number(id))?.title||'—';
const options=computed(()=>({customers:['服务中','暂停服务','已归档'],contracts:['执行中','待签约','已到期','已终止'],tasks:['未开始','进行中','已完成'],bills:['增值税专用发票','增值税普通发票','收据','银行回单','其他'],receivables:['未收款','部分收款','已收清']}[props.page]||[]));
const rows=computed(()=>{
  let list=props.state[props.page]||[];
  return list.filter(x=>{
    if(customer.value&&Number(x.customer_id)!==Number(customer.value)&&props.page!=='customers')return false;
    if(status.value&&(props.page==='bills'?x.type:x.status)!==status.value)return false;
    if(props.page==='contracts'&&expired.value&&!(x.status==='已到期'||(x.status==='执行中'&&x.end_date<today())))return false;
    if(props.page==='contracts'&&expiresSoon.value){const last=new Date();last.setDate(last.getDate()+30);const limit=`${last.getFullYear()}-${String(last.getMonth()+1).padStart(2,'0')}-${String(last.getDate()).padStart(2,'0')}`;if(x.status!=='执行中'||x.end_date<today()||x.end_date>limit)return false;}
    if(month.value&&!String(x.month||x.date||x.due_date||'').startsWith(month.value))return false;
    if(endBefore.value&&String(x.end_date||x.due_date||x.date||'')>endBefore.value)return false;
    if(onlyOverdue.value){if(props.page==='receivables'&&(!(x.balance_cents>0)||x.due_date>=today()))return false;if(props.page==='tasks'&&(x.due_date>=today()||done(x)===5))return false;}
    if(query.value&&!`${x.name||''} ${x.title||''} ${x.contact||''} ${x.phone||''} ${x.number||''} ${x.description||''} ${x.notes||''} ${cname(x.customer_id)}`.toLowerCase().includes(query.value.toLowerCase()))return false;
    return true;
  });
});
const done=t=>(t.steps||[]).filter(s=>s.status==='已完成').length;
const paid=id=>(props.state.payments||[]).filter(p=>p.receivable_id===id);
const badge=s=>['已完成','已收清','服务中','执行中'].includes(s)?'success':['暂停服务','进行中','部分收款','待签约'].includes(s)?'warning':s==='已到期'?'danger':'muted';
const activeCustomers=computed(()=>customers.value.filter(c=>c.status!=='已归档'));
function resetFilters(){query.value='';status.value='';customer.value='';month.value='';endBefore.value='';onlyOverdue.value=false;expiresSoon.value=false;expired.value=false;}
watch(()=>[props.page,props.filter],()=>{
  resetFilters();error.value='';notice.value='';modal.value='';
  if(props.filter?.customer_id)customer.value=props.filter.customer_id;
  if(props.filter?.status)status.value=props.filter.status;
  if(props.filter?.month)month.value=props.filter.month;
  if(props.filter?.overdue)onlyOverdue.value=true;
  if(props.filter?.endBefore)endBefore.value=props.filter.endBefore;
  if(props.filter?.expiresSoon)expiresSoon.value=true;
  if(props.filter?.expired)expired.value=true;
  if(props.filter?.action==='new')open();
},{immediate:true});
function open(row){
  error.value='';files.value=[];detail.value=null;modal.value=props.page;
  if(row){form.value=JSON.parse(JSON.stringify(row));if(row.amount_cents!==undefined)form.value.amount=yuan(row.amount_cents).replaceAll(',','');return;}
  const first=activeCustomers.value[0]?.id||'';
  const defaults={customers:{name:'',contact:'',phone:'',status:'服务中',notes:'',tax_no:''},contracts:{customer_id:first,title:'代账服务合同',content:'记账、复核、申报准备与处理状态跟踪',start_date:today(),end_date:`${Number(today().slice(0,4))+1}${today().slice(4)}`,amount:'',cycle:'按月',status:'执行中',notes:''},tasks:{customer_id:first,month:today().slice(0,7),due_date:today(),steps:stepKeys.map(key=>({key,status:'未开始',date:'',notes:''}))},bills:{customer_id:first,date:today(),type:'增值税普通发票',amount:'',number:'',notes:''},receivables:{contract_id:props.state.contracts?.[0]?.id||'',amount:'',due_date:today(),description:''}};
  form.value=defaults[props.page]||{};
}
async function save(){
  busy.value=true;error.value='';
  try{
    const data={...form.value};
    if(['contracts','bills','receivables','payments'].includes(modal.value)){data.amount_cents=cents(data.amount);delete data.amount;}
    for(const k of ['customer_id','contract_id','receivable_id'])if(data[k])data[k]=Number(data[k]);
    const entity=modal.value;
    const result=await api(`/${entity}${data.id?'/'+data.id:''}`,data,data.id?'PUT':'POST');
    if(entity==='bills'&&files.value.length){
      const id=result?.id||data.id;form.value.id=id;
      for(const file of files.value){if(file.size>10*1024*1024)throw new Error('票据已保存；附件最大支持 10 MB，请选择较小文件后重试');await api(`/bills/${id}/attachments`,{name:file.name,mime:file.type||'application/octet-stream',content:await fileBase64(file)});files.value=files.value.filter(pending=>pending!==file);}
    }
    modal.value='';emit('changed','保存成功，统计已更新');
  }catch(e){error.value=e.message;emit('changed');}finally{busy.value=false;}
}
async function archive(row){if(!confirm(`归档「${row.name}」？历史合同、任务和财务记录将保留。`))return;await action(()=>api('/customers/'+row.id,{...row,status:'已归档'},'PUT'),'客户已归档');}
async function action(fn,msg){busy.value=true;error.value='';try{await fn();notice.value=msg;emit('changed',msg);}catch(e){error.value=e.message;}finally{busy.value=false;}}
function payment(row){error.value='';modal.value='payments';form.value={receivable_id:row.id,date:today(),amount:units(row.balance_cents),method:'银行转账',notes:''};}
function view(row){detail.value=row;modal.value='detail';error.value='';}
const reportRows=computed(()=>customers.value.map(c=>{const tasks=(props.state.tasks||[]).filter(t=>t.customer_id===c.id&&(!month.value||t.month===month.value));const ar=(props.state.receivables||[]).filter(r=>r.customer_id===c.id&&(!month.value||r.due_date.startsWith(month.value)));return {...c,tasks:tasks.length,completed:tasks.filter(t=>done(t)===5).length,progress:tasks.length?Math.round(tasks.reduce((s,t)=>s+done(t),0)/(tasks.length*5)*100):0,due:ar.reduce((s,r)=>s+r.amount_cents,0),received:ar.reduce((s,r)=>s+r.received_cents,0),balance:ar.reduce((s,r)=>s+r.balance_cents,0),overdue:ar.filter(r=>r.due_date<today()).reduce((s,r)=>s+r.balance_cents,0)};}).filter(c=>!customer.value||c.id===Number(customer.value)));
const totals=computed(()=>reportRows.value.reduce((a,r)=>({due:a.due+r.due,received:a.received+r.received,balance:a.balance+r.balance,overdue:a.overdue+r.overdue}),{due:0,received:0,balance:0,overdue:0}));
async function exportReport(){
 const table=[['客户名称','任务数','完成数','进度(%)','应收(元)','已收(元)','未收(元)','逾期未收(元)'],...reportRows.value.map(r=>[r.name,r.tasks,r.completed,r.progress,units(r.due),units(r.received),units(r.balance),units(r.overdue)])];
 const quote=x=>'"'+String(x).replace(/^[\s]*[=+@-]|^[\t\r]/,"'$&").replaceAll('"','""')+'"';
 const url=URL.createObjectURL(new Blob(['\uFEFF'+table.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='客户业务汇总.csv';a.click();URL.revokeObjectURL(url);
}
async function downloadBackup(){
  await action(async()=>{const response=await fetch('/api/backup');if(!response.ok){const result=await response.json();throw new Error(result.message||'备份下载失败');}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=`yundaizhang-${today()}.json.gz`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'完整备份已生成，请妥善保存下载文件');
}
async function restore(){if(restoreConfirm.value!=='恢复备份'){error.value='请先输入“恢复备份”确认替换当前数据';return;}if(!restoreFile.value){error.value='请选择本软件导出的备份文件';return;}if(restoreFile.value.size>96*1024*1024){error.value='应用内备份文件最大 96 MiB；更大的数据库请停止服务后复制完整 data 文件夹';return;}await action(()=>fileBase64(restoreFile.value).then(content=>api('/restore',{content})),'备份已恢复，恢复前数据已自动另存备份');restoreConfirm.value='';}
</script>

<template>
  <section class="business-view">
    <div class="page-heading"><div><h1 class="page-title">{{cfg.title}}</h1><p class="page-description">{{cfg.desc}}</p></div><div class="actions"><a v-if="cfg.add" class="btn btn-secondary" :href="'/api/export/'+page">导出 CSV</a><button v-if="cfg.add" class="btn btn-primary" @click="open()">＋ {{cfg.add}}</button></div></div>
    <div v-if="error&&!modal" class="notice error" role="alert">{{error}}</div><div v-if="notice" class="notice success" role="status">{{notice}}</div>
    <template v-if="cfg.add">
      <div class="card toolbar"><input v-model="query" class="search-input" aria-label="搜索" placeholder="搜索客户、编号或备注…"><select v-if="page!=='customers'" v-model="customer" aria-label="按客户筛选"><option value="">全部客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="status" aria-label="按状态筛选"><option value="">{{page==='bills'?'全部类型':'全部状态'}}</option><option v-for="s in options" :key="s">{{s}}</option></select><input v-if="['tasks','bills','receivables'].includes(page)" v-model="month" type="month" aria-label="按月份筛选"><label v-if="['contracts','receivables'].includes(page)" class="inline-label">到期不晚于 <input v-model="endBefore" type="date"></label><label v-if="['tasks','receivables'].includes(page)" class="check-label"><input v-model="onlyOverdue" type="checkbox">只看逾期</label><span v-if="expiresSoon" class="badge warning">30 天内到期</span><span v-if="expired" class="badge danger">已到期待续签</span><button class="btn btn-ghost" @click="resetFilters">重置</button></div>
      <div class="card table-wrap"><div class="table-meta"><span>共 <b>{{rows.length}}</b> 条记录</span><span v-if="page==='tasks'" class="text-muted">税务进度仅为本地工作记录</span></div>
        <table class="data-table" v-if="page==='customers'"><thead><tr><th>企业名称</th><th>联系人</th><th>联系方式</th><th>服务状态</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><button class="table-link" @click="view(r)">{{r.name}}</button><small class="cell-sub">{{r.tax_no||'未填写纳税人识别号'}}</small></td><td>{{r.contact||'—'}}</td><td>{{r.phone||'—'}}</td><td><span class="badge" :class="badge(r.status)">{{r.status}}</span></td><td class="truncate-cell">{{r.notes||'—'}}</td><td class="actions"><button class="table-link" @click="open(r)">编辑</button><button class="table-link" @click="emit('navigate','tasks',{customer_id:r.id})">任务</button><button v-if="r.status!=='已归档'" class="table-link danger-text" @click="archive(r)">归档</button></td></tr></tbody></table>
        <table class="data-table" v-if="page==='contracts'"><thead><tr><th>合同 / 客户</th><th>服务期限</th><th>费用</th><th>收款周期</th><th>合同状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><button class="table-link" @click="view(r)">{{r.title}}</button><small class="cell-sub">{{cname(r.customer_id)}}</small></td><td>{{r.start_date}} 至 {{r.end_date}}</td><td class="money">¥{{yuan(r.amount_cents)}}</td><td>{{r.cycle}}</td><td><span class="badge" :class="badge(r.status)">{{r.status}}</span><small class="cell-sub danger-text" v-if="r.end_date<today()&&r.status==='执行中'">服务期限已到期</small></td><td class="actions"><button class="table-link" @click="open(r)">编辑</button><button class="table-link" @click="emit('navigate','receivables',{customer_id:r.customer_id})">应收</button></td></tr></tbody></table>
        <table class="data-table" v-if="page==='tasks'"><thead><tr><th>客户 / 会计月份</th><th v-for="(label,key) in stepLabels" :key="key">{{label}}</th><th>截止日</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{cname(r.customer_id)}}</strong><small class="cell-sub">{{r.month}} · 已完成 {{done(r)}} / 5</small></td><td v-for="key in stepKeys" :key="key"><span class="badge" :class="badge(r.steps?.find(s=>s.key===key)?.status)">{{r.steps?.find(s=>s.key===key)?.status||'未开始'}}</span><small class="cell-sub">{{r.steps?.find(s=>s.key===key)?.date||'—'}}</small></td><td :class="{'danger-text':r.due_date<today()&&done(r)<5}">{{r.due_date}}<small class="cell-sub" v-if="r.due_date<today()&&done(r)<5">已逾期</small></td><td><button class="table-link" @click="open(r)">更新进度</button></td></tr></tbody></table>
        <table class="data-table" v-if="page==='bills'"><thead><tr><th>票据编号 / 客户</th><th>日期</th><th>类型</th><th>金额</th><th>本地附件</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.number||'未编号'}}</strong><small class="cell-sub">{{cname(r.customer_id)}}</small></td><td>{{r.date}}</td><td>{{r.type}}</td><td class="money">¥{{yuan(r.amount_cents)}}</td><td><a v-for="a in r.attachments||[]" :key="a.id" class="attachment-link" :href="'/api/attachments/'+a.id">↧ {{a.name}}</a><span v-if="!r.attachments?.length" class="text-muted">无附件</span></td><td><button class="table-link" @click="open(r)">编辑 / 附件</button></td></tr></tbody></table>
        <table class="data-table" v-if="page==='receivables'"><thead><tr><th>客户 / 合同</th><th>应收金额</th><th>已收 / 未收</th><th>到期日</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{cname(r.customer_id)}}</strong><small class="cell-sub">{{ctitle(r.contract_id)}} · {{r.description||'服务费'}}</small></td><td class="money">¥{{yuan(r.amount_cents)}}</td><td><span class="success-text">已收 ¥{{yuan(r.received_cents)}}</span><small class="cell-sub">未收 ¥{{yuan(r.balance_cents)}}</small></td><td>{{r.due_date}}</td><td><span class="badge" :class="badge(r.status)">{{r.status}}</span><small v-if="r.balance_cents>0&&r.due_date<today()" class="cell-sub danger-text">逾期未收</small></td><td class="actions"><button v-if="r.balance_cents>0" class="table-link" @click="payment(r)">登记收款</button><button class="table-link" @click="view(r)">收款明细</button><button class="table-link" @click="open(r)">编辑应收</button></td></tr></tbody></table>
        <div v-if="!rows.length" class="empty-state"><div class="empty-symbol">▤</div><h3>暂无{{cfg.title}}记录</h3><p>新增第一条业务记录，相关统计会自动更新。</p><button class="btn btn-primary" @click="open()">{{cfg.add}}</button></div>
      </div>
    </template>

    <template v-if="page==='reports'">
      <div class="card toolbar"><select v-model="customer" aria-label="报表客户"><option value="">全部客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select><input v-model="month" type="month" aria-label="汇总月份"><button class="btn btn-ghost" @click="resetFilters">全部月份</button><button class="btn btn-primary" @click="exportReport">导出当前汇总 CSV</button></div>
      <p class="notice">{{month||'全部月份'}}：任务按会计月份；应收按到期月份，已收为这些应收截至当前的累计收款。</p>
      <div class="report-stats"><div class="card"><span>合同应收</span><strong>¥{{yuan(totals.due)}}</strong></div><div class="card"><span>累计已收</span><strong class="success-text">¥{{yuan(totals.received)}}</strong></div><div class="card"><span>剩余未收</span><strong>¥{{yuan(totals.balance)}}</strong></div><div class="card"><span>逾期未收</span><strong class="danger-text">¥{{yuan(totals.overdue)}}</strong></div></div>
      <div class="card table-wrap"><table class="data-table"><thead><tr><th>客户</th><th>任务数</th><th>已完成</th><th>步骤完成率</th><th>应收</th><th>已收</th><th>未收</th><th>逾期未收</th></tr></thead><tbody><tr v-for="r in reportRows" :key="r.id"><td>{{r.name}}</td><td>{{r.tasks}}</td><td>{{r.completed}}</td><td>{{r.progress}}%</td><td>¥{{yuan(r.due)}}</td><td>¥{{yuan(r.received)}}</td><td>¥{{yuan(r.balance)}}</td><td :class="{'danger-text':r.overdue>0}">¥{{yuan(r.overdue)}}</td></tr></tbody></table><div v-if="!reportRows.length" class="empty-state">暂无客户记录</div></div>
    </template>

    <template v-if="page==='maintenance'">
      <div class="maintenance-grid"><article class="card settings-card"><div class="section-kicker">LOCAL STORAGE</div><h2>本机数据存储</h2><p>业务记录、凭证和票据附件均存入 SQLite 数据库。</p><dl class="info-list"><dt>运行模式</dt><dd>本机单人使用 · 无需登录</dd><dt>数据库文件</dt><dd class="path-text">{{state.system?.db_path||'数据目录加载中'}}</dd><dt>备份目录</dt><dd class="path-text">{{state.system?.data_dir}} / backups</dd></dl><p class="text-muted">关闭浏览器不会清空数据。复制整个 data 文件夹或使用完整备份，可迁移到其他电脑。</p></article>
      <article class="card settings-card"><div class="section-kicker">BACKUP</div><h2>完整数据备份</h2><p>包含客户、合同、任务、收款、凭证、科目与票据附件。建议每次批量录入后备份。</p><button class="btn btn-primary" :disabled="busy" @click="downloadBackup">↧ 下载完整备份</button><p class="text-muted">备份含业务信息，请存放在你信任的本地位置。压缩文件限 96 MiB，展开限 128 MiB；更大数据请停止服务后复制整个 data 文件夹。</p></article>
      <article class="card settings-card"><div class="section-kicker">RESTORE</div><h2>从备份恢复</h2><p>恢复会替换当前全部业务记录。系统校验文件后，在事务内恢复，并自动保留恢复前备份。</p><label class="field"><span>选择本软件导出的备份文件</span><input type="file" accept=".json,.gz,.backup,.ydz" @change="restoreFile=$event.target.files[0]"></label><label class="field"><span>输入“恢复备份”确认替换</span><input v-model="restoreConfirm" placeholder="恢复备份" autocomplete="off"></label><button class="btn btn-danger" :disabled="busy" @click="restore">校验并恢复数据</button></article>
      <article class="card settings-card"><div class="section-kicker">GET STARTED</div><h2>可选虚构示例</h2><p>空数据库可载入示例企业、代账任务、合同和凭证，体验完整操作。示例不会混入已有业务数据。</p><button class="btn btn-secondary" :disabled="busy||customers.length>0" @click="action(()=>api('/demo',{}),'虚构示例已载入')">{{customers.length?'数据库已有记录，不能载入示例':'载入虚构示例数据'}}</button><hr><h3>后续功能</h3><p class="text-muted">多人权限、移动端、发票识别、工资、固定资产和现金流量表待后续实现。真实税务、发票及支付平台未接入。</p></article></div>
      <article class="card settings-card"><h2>业务数据 CSV</h2><p class="text-muted">以 UTF-8 格式导出，金额精确到分，可在 Excel 中打开。</p><div class="actions"><a v-for="(label,key) in {customers:'客户档案',contracts:'代账合同',tasks:'月度任务',bills:'票据记录',receivables:'应收明细',payments:'逐笔收款'}" :key="key" class="btn btn-secondary" :href="'/api/export/'+key">{{label}} CSV</a></div></article><article class="card settings-card audit-card"><h2>最近操作记录</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>时间</th><th>操作</th><th>详情</th></tr></thead><tbody><tr v-for="l in (state.logs||[]).slice(0,30)" :key="l.id"><td>{{l.created_at||l.date}}</td><td>{{l.action}}</td><td>{{l.detail||l.details||l.entity||'—'}}</td></tr></tbody></table><p v-if="!state.logs?.length" class="text-muted">暂无操作记录</p></div></article>
    </template>

    <Teleport to="body"><div v-if="modal" class="modal-mask" @click.self="!busy&&(modal='')"><section class="modal" :class="{'modal-wide':modal==='tasks'}" role="dialog" aria-modal="true" :aria-label="modal==='detail'?'查看详情':(form.id?'编辑记录':'新增记录')"><div class="modal-header"><h2>{{modal==='detail'?'记录详情':modal==='payments'?'登记收款':`${form.id?'编辑':'新增'}${{customers:'客户',contracts:'合同',tasks:'月度任务',bills:'票据',receivables:'应收'}[modal]}`}}</h2><button class="btn btn-ghost" :disabled="busy" aria-label="关闭弹窗" @click="modal=''">✕</button></div>
      <form v-if="modal!=='detail'" @submit.prevent="save"><div class="modal-body"><div v-if="error" class="notice error" role="alert">{{error}}</div>
        <div class="form-grid">
          <template v-if="modal==='customers'"><label class="field full"><span>企业名称 *</span><input v-model="form.name" required maxlength="120"></label><label class="field"><span>联系人</span><input v-model="form.contact" maxlength="80"></label><label class="field"><span>联系方式</span><input v-model="form.phone" maxlength="80"></label><label class="field"><span>服务状态</span><select v-model="form.status"><option>服务中</option><option>暂停服务</option><option>已归档</option></select></label><label class="field"><span>纳税人识别号（选填）</span><input v-model="form.tax_no" maxlength="50"></label></template>
          <label v-if="['contracts','tasks','bills'].includes(modal)" class="field full"><span>所属客户 *</span><select v-model="form.customer_id" required><option value="" disabled>请先新增客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}} {{c.status==='已归档'?'（已归档）':''}}</option></select></label>
          <template v-if="modal==='contracts'"><label class="field full"><span>合同名称 *</span><input v-model="form.title" required maxlength="160"></label><label class="field full"><span>服务内容 *</span><textarea v-model="form.content" required rows="2"></textarea></label><label class="field"><span>开始日期 *</span><input v-model="form.start_date" type="date" required></label><label class="field"><span>到期日期 *</span><input v-model="form.end_date" type="date" :min="form.start_date" required></label><label class="field"><span>合同总费用（元）*</span><input v-model="form.amount" type="number" min="0.01" step="0.01" required></label><label class="field"><span>收款周期</span><select v-model="form.cycle"><option>按月</option><option>按季</option><option>半年</option><option>按年</option><option>一次性</option></select></label><label class="field"><span>合同状态</span><select v-model="form.status"><option>执行中</option><option>待签约</option><option>已到期</option><option>已终止</option></select></label><p class="text-muted">合同不会自动生成应收；请在“应收与收款”中按约定周期登记各期应收。</p></template>
          <template v-if="modal==='tasks'"><label class="field"><span>会计月份 *</span><input v-model="form.month" type="month" required></label><label class="field"><span>任务截止日 *</span><input v-model="form.due_date" type="date" required></label><div class="full notice">“申报准备 / 处理”仅记录工作状态；不代表已完成真实税务申报。</div><div v-for="s in form.steps" :key="s.key" class="task-step-editor full"><strong>{{stepLabels[s.key]}}</strong><label class="field"><span>状态</span><select v-model="s.status" :aria-label="stepLabels[s.key]+'状态'"><option>未开始</option><option>进行中</option><option>已完成</option></select></label><label class="field"><span>日期</span><input v-model="s.date" type="date" :aria-label="stepLabels[s.key]+'日期'"></label><label class="field step-notes"><span>备注</span><input v-model="s.notes" placeholder="本步骤的处理记录"></label></div></template>
          <template v-if="modal==='bills'"><label class="field"><span>票据日期 *</span><input v-model="form.date" type="date" required></label><label class="field"><span>票据类型</span><select v-model="form.type"><option v-for="t in ['增值税专用发票','增值税普通发票','收据','银行回单','其他']" :key="t">{{t}}</option></select></label><label class="field"><span>金额（元）*</span><input v-model="form.amount" type="number" min="0.01" step="0.01" required></label><label class="field"><span>票据编号</span><input v-model="form.number" maxlength="100"></label><label class="field full"><span>添加本地附件（每个最大 10 MB）</span><input type="file" multiple @change="files=Array.from($event.target.files)"></label><div v-if="form.attachments?.length" class="full"><a v-for="a in form.attachments" :key="a.id" class="attachment-link" :href="'/api/attachments/'+a.id">↧ {{a.name}}</a></div></template>
          <template v-if="modal==='receivables'"><label class="field full"><span>对应合同 *</span><select v-model="form.contract_id" required><option value="" disabled>请先新增合同</option><option v-for="c in state.contracts||[]" :key="c.id" :value="c.id">{{cname(c.customer_id)}} · {{c.title}}</option></select></label><label class="field"><span>本期应收金额（元）*</span><input v-model="form.amount" type="number" min="0.01" step="0.01" required></label><label class="field"><span>到期日 *</span><input v-model="form.due_date" type="date" required></label><label class="field full"><span>应收说明</span><input v-model="form.description" placeholder="例如：2026 年 10 月代账服务费"></label></template>
          <template v-if="modal==='payments'"><label class="field"><span>收款日期 *</span><input v-model="form.date" type="date" required></label><label class="field"><span>本次实收金额（元）*</span><input v-model="form.amount" type="number" min="0.01" step="0.01" required></label><label class="field full"><span>收款方式</span><select v-model="form.method"><option>银行转账</option><option>现金</option><option>微信</option><option>支付宝</option><option>其他</option></select></label><p class="full text-muted">仅登记你已收到的款项，不会发起真实支付。</p></template>
          <label v-if="!['tasks','receivables'].includes(modal)" class="field full"><span>备注</span><textarea v-model="form.notes" rows="3" maxlength="2000"></textarea></label>
        </div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" :disabled="busy" @click="modal=''">取消</button><button type="submit" class="btn btn-primary" :disabled="busy">{{busy?'保存中…':'保存记录'}}</button></div></form>
      <div v-else class="modal-body"><template v-if="page==='receivables'"><h3>{{cname(detail.customer_id)}} · {{ctitle(detail.contract_id)}}</h3><p>应收 ¥{{yuan(detail.amount_cents)}} · 已收 ¥{{yuan(detail.received_cents)}} · 未收 ¥{{yuan(detail.balance_cents)}}</p><table class="data-table"><thead><tr><th>收款日期</th><th>实收金额</th><th>方式</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="p in paid(detail.id)" :key="p.id"><td>{{p.date}}</td><td>¥{{yuan(p.amount_cents)}}</td><td>{{p.method}}</td><td>{{p.notes||'—'}}</td><td><button class="table-link" @click="form={...p,amount:units(p.amount_cents)};modal='payments'">更正</button></td></tr></tbody></table><p v-if="!paid(detail.id).length" class="text-muted">尚无收款记录</p></template><template v-else-if="page==='customers'"><h3>{{detail.name}}</h3><dl class="info-list"><dt>联系人</dt><dd>{{detail.contact||'—'}}</dd><dt>联系方式</dt><dd>{{detail.phone||'—'}}</dd><dt>服务状态</dt><dd>{{detail.status}}</dd><dt>备注</dt><dd>{{detail.notes||'—'}}</dd></dl><div class="actions"><button class="btn btn-secondary" @click="modal='';emit('navigate','contracts',{customer_id:detail.id})">查看合同</button><button class="btn btn-primary" @click="modal='';emit('navigate','vouchers',{customer_id:detail.id})">查看凭证</button></div></template><template v-else><h3>{{detail.title}}</h3><p>{{cname(detail.customer_id)}} · {{detail.start_date}} 至 {{detail.end_date}}</p><h4>服务内容</h4><p class="pre-wrap">{{detail.content}}</p><p>合同金额 ¥{{yuan(detail.amount_cents)}} · {{detail.cycle}} · {{detail.status}}</p><p>{{detail.notes}}</p></template></div>
    </section></div></Teleport>
  </section>
</template>
